class Solution {
    private int[] tree;
    private int maxVal;

    private void update(int idx, int val) {
        for (; idx <= maxVal; idx += idx & (-idx)) tree[idx] += val;
    }

    private int query(int idx) {
        int s = 0;
        for (; idx > 0; idx -= idx & (-idx)) s += tree[idx];
        return s;
    }

    public int createSortedArray(int[] instructions) {
        long MOD = 1000000007L;
        maxVal = 0;
        for (int x : instructions) maxVal = Math.max(maxVal, x);
        maxVal++;
        tree = new int[maxVal + 1];
        long totalCost = 0;
        for (int i = 0; i < instructions.length; ++i) {
            int x = instructions[i];
            int less = query(x - 1);
            int greater = i - query(x);
            totalCost = (totalCost + Math.min(less, greater)) % MOD;
            update(x, 1);
        }
        return (int)totalCost;
    }
}

