    let maxVal = 0;
    for (const x of instructions) {
        if (x > maxVal) maxVal = x;
    }
    maxVal++;
    const tree = Array(maxVal + 1).fill(0);

    function update(idx, val) {
        for (; idx <= maxVal; idx += idx & (-idx)) tree[idx] += val;
    }

    function query(idx) {
        let s = 0;
        for (; idx > 0; idx -= idx & (-idx)) s += tree[idx];
        return s;
    }

